seo_schema:
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What is Varun Vihar Yojana Lucknow?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Varun Vihar Yojana is LDA's largest ever planned residential and infrastructure scheme — spread across 6,580 acres (approximately 10,613 bigha) along the Agra Expressway in Lucknow. It will have 25 sectors, 15,000+ plots, a 300-acre logistics park, an ISBT, an international golf course, and 800 acres of green belt. It is officially described by LDA as the largest residential scheme in the state."
      }
    },
    {
      "@type": "Question",
      "name": "Where exactly is Varun Vihar in Lucknow?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Varun Vihar is on the Agra Expressway — in the Sadar and Sarojini Nagar tehsils of Lucknow district. It spans 12 villages: Bhalia, Adampur Indwara, Bahru, Jaliyamau, Madarpur, Ibrahimganj, Nakataura, Gehlwara, Tejkrishna Kheda, Rewari, Sakra and Dona."
      }
    },
    {
      "@type": "Question",
      "name": "How many plots will Varun Vihar have?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "LDA has confirmed more than 15,000 residential, commercial and group housing plots across all income categories — EWS, LIG, MIG and HIG. These will be allotted through a transparent computerised lottery system when launched."
      }
    },
    {
      "@type": "Question",
      "name": "What is the 300-acre logistics park in Varun Vihar?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A dedicated 300-acre industrial-grade logistics park with direct connectivity to the Agra Expressway and Kisan Path. It is designed to make Lucknow a major logistics hub of North India, generating thousands of employment opportunities in warehousing, supply chain and trade."
      }
    },
    {
      "@type": "Question",
      "name": "Has the Varun Vihar lottery been announced?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. As of March 2026, Varun Vihar is in the land acquisition phase. LDA has completed registry of approximately 450 bigha and distributed Rs 300 crore in farmer compensation — but no public lottery has been announced. Monitor ldalucknow.in for updates."
      }
    },
    {
      "@type": "Question",
      "name": "Is it safe to buy land near Varun Vihar right now?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Exercise extreme caution. Land in the 12 villages under acquisition may be subject to government proceedings. Always check the Khatauni at upbhulekh.gov.in, verify acquisition status with LDA, get an Encumbrance Certificate, and confirm no government claim exists before paying anyone. A professional verification before any transaction is strongly recommended."
      }
    },
    {
      "@type": "Question",
      "name": "What makes Varun Vihar different from IT City and Wellness City?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Three key differences: First, it is the largest — 6,580 acres versus 3,490 for IT City and 1,474 for Wellness City. Second, it is on the Agra Expressway, not Sultanpur Road. Third, it has a unique 300-acre logistics park — no other LDA township has this. It is a logistics plus residential township, not a technology or health township."
      }
    },
    {
      "@type": "Question",
      "name": "What is the expected plot price in Varun Vihar?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No official pricing has been announced as of March 2026. Based on LDA's pattern with IT City and Wellness City, expect launch pricing below prevailing market rates for the area. Sultanpur Road corridor is Rs 3,500 to Rs 5,000 per sqft — Agra Expressway corridor pricing will differ. Verify at ldalucknow.in when registration opens."
      }
    },
    {
      "@type": "Question",
      "name": "How many villages are in Varun Vihar?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "12 villages: Bhalia, Adampur Indwara, Bahru, Jaliyamau, Madarpur, Ibrahimganj, Nakataura, Gehlwara, Tejkrishna Kheda, Rewari, Sakra and Dona — all in Sadar and Sarojini Nagar tehsils, Lucknow district."
      }
    },
    {
      "@type": "Question",
      "name": "Is Varun Vihar a good investment in 2026?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Varun Vihar has exceptional long-term fundamentals — India's largest LDA scheme, logistics park, golf course, 800 acres green belt, Agra Expressway connectivity. But it is a 5 to 7 year horizon investment. Development has not started. Do not expect quick returns or early possession. Always verify any land or plot transaction with a professional before paying."
      }
    },
    {
      "@type": "Question",
      "name": "When is the Varun Vihar Yojana Lucknow launch date?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "LDA has not announced a confirmed public registration date for Varun Vihar Yojana as of May 2026. The scheme is still in its land acquisition phase. Media reports point to a possible Phase 1 launch around June 2026 with roughly 2,100 plots, but this is an estimate, not an official date. The confirmed notification will appear on ldalucknow.in."
      }
    },
    {
      "@type": "Question",
      "name": "What is the Varun Vihar Yojana plot price per sq ft?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "LDA's 2026 scheme pricing indicates Varun Vihar plots starting at around Rs 3,252 per square foot, which makes it one of the more affordable LDA plotted schemes. This is an indicative figure, not a final allotment rate. Actual prices vary by category, plot size and location within the scheme, and will be confirmed in the official registration notification."
      }
    }
  ]
}
